def classify_froude(fr):
  if fr < 0.95:
	  return "fluvial"
  if fr < 1.0:
	  return "near-critical (slow)"
  if fr == 1.0:
	  return "critical"
  if fr <= 1.05:
	  return "near-critical (fast)"
  return "super-critical"

